class ScopedArtifactService {
  constructor(delegate, appName, userId, sessionId) {
    this.delegate = delegate;
    this.appName = appName;
    this.userId = userId;
    this.sessionId = sessionId;
  }
  async saveArtifact(request) {
    return this.delegate.saveArtifact({
      appName: this.appName,
      userId: this.userId,
      sessionId: this.sessionId,
      ...request
    });
  }
  async loadArtifact(request) {
    return this.delegate.loadArtifact({
      appName: this.appName,
      userId: this.userId,
      sessionId: this.sessionId,
      ...request
    });
  }
  async listArtifactKeys() {
    return this.delegate.listArtifactKeys({
      appName: this.appName,
      userId: this.userId,
      sessionId: this.sessionId
    });
  }
  async deleteArtifact(filename) {
    return this.delegate.deleteArtifact({
      appName: this.appName,
      userId: this.userId,
      sessionId: this.sessionId,
      filename
    });
  }
  async listVersions(filename) {
    return this.delegate.listVersions({
      appName: this.appName,
      userId: this.userId,
      sessionId: this.sessionId,
      filename
    });
  }
  async listArtifactVersions(filename) {
    return this.delegate.listArtifactVersions({
      appName: this.appName,
      userId: this.userId,
      sessionId: this.sessionId,
      filename
    });
  }
  async getArtifactVersion(request) {
    return this.delegate.getArtifactVersion({
      appName: this.appName,
      userId: this.userId,
      sessionId: this.sessionId,
      ...request
    });
  }
}
export {
  ScopedArtifactService
};
